using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Forms;

internal static class ProgramUpdateNotesTests {
    static int checks;const BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
    static void Need(bool value,string message){checks++;if(!value)throw new Exception(message);}
    static T Field<T>(object target,string key){return (T)target.GetType().GetField(key,Private).GetValue(target);}
    static void Set(object target,string key,object value){target.GetType().GetField(key,Private).SetValue(target,value);}
    static void Invoke(object target,string key){target.GetType().GetMethod(key,Private).Invoke(target,null);}
    static void Until(Func<bool> condition,string message){var clock=Stopwatch.StartNew();while(!condition()&&clock.ElapsedMilliseconds<10000){Application.DoEvents();Thread.Sleep(5);}Need(condition(),message);}
    static void Write(string path,object value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,Json.Serialize(value),new UTF8Encoding(false));}
    static SoftwareFile FileRecord(string root,string relative){string path=Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar));return new SoftwareFile{path=relative,bytes=new FileInfo(path).Length,sha256=SoftwareUpdate.Hash(path)};}
    sealed class Fixture {
        public string Root,State,Tag,Relative,NoteText,Transaction;public Version Version;public SoftwareManifest Inventory;
        public Fixture(string folder){Root=Path.Combine(folder,"program");State=Path.Combine(folder,"state");Version=typeof(Manager).Assembly.GetName().Version;Tag="v"+Version.Major+"."+Version.Minor+"."+Version.Build+"-preview.888";Relative="docs/release-"+Tag.Substring(1)+".md";Directory.CreateDirectory(Path.Combine(Root,"docs"));Directory.CreateDirectory(State);File.Copy(Assembly.GetExecutingAssembly().Location,Path.Combine(Root,"CodexLiveBackground.exe"));NoteText="# "+Tag+"\r\n\r\n内部版本："+Version+"。\r\n\r\n- **配色跟随组件**，现有设置保留。\r\n- 更新后显示[本版说明](https://example.invalid/notes)。\r\n";Restore();}
        public void Restore(){File.WriteAllText(Path.Combine(Root,Relative.Replace('/',Path.DirectorySeparatorChar)),NoteText,new UTF8Encoding(false));Inventory=new SoftwareManifest{version=Version.ToString(),files=new[]{FileRecord(Root,"CodexLiveBackground.exe"),FileRecord(Root,Relative)}};Write(Path.Combine(Root,"manifest.json"),Inventory);}
        public void Receipt(bool pass=true,string owner=null,string version=null,bool changeNotes=true){Transaction=Path.Combine(State,"updates","rollback-fixture");Directory.CreateDirectory(Path.Combine(Transaction,"incoming"));Directory.CreateDirectory(Path.Combine(Transaction,"previous"));Write(Path.Combine(Transaction,"previous",".codex-background-install.json"),new{productId="codex-live-background/exe",root=owner??Root});Write(Path.Combine(Transaction,"incoming","update-manifest.json"),new SoftwareManifest{product="CodexHub-program-update",version=version??Version.ToString(),files=Inventory.files});Write(Path.Combine(Transaction,"result.json"),new{pass,version=version??Version.ToString(),changed=changeNotes?new[]{"CodexLiveBackground.exe",Relative}:new[]{"CodexLiveBackground.exe"},materialsUnchanged=true,settingsUnchanged=true});}
    }
    static void Lookup(UpdateLookupState lookup,Version version){lock(lookup.Gate){lookup.HasCache=true;lookup.Cached=new SoftwareRelease{version=version.ToString(),tag="v"+version.Major+"."+version.Minor+"."+version.Build+"-preview.999",url="https://example.invalid/never-download",sha256=new string('a',64),bytes=1};lookup.CachedUntilUtc=DateTime.UtcNow.AddHours(1);}}
    [STAThread]static int Main(string[] args){string report=args[1],folder=Path.Combine(Path.GetDirectoryName(report),"notes-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{
        var fixture=new Fixture(folder);var notes=LocalProgramNotes.Read(fixture.Root,fixture.Version);Need(notes!=null&&notes.Tag==fixture.Tag,"Current verified release notes were not mapped to the internal version");Need(notes.Body.Contains("• 配色跟随组件")&&!notes.Body.Contains("**")&&!notes.Body.Contains("https://"),"Release notes were not converted into compact text");
        string current=LocalProgramNotes.CurrentLog(fixture.Root,"CodexHub · 测试当前版",fixture.Version);Need(current.Contains("测试当前版")&&current.Contains(fixture.Version.ToString())&&current.Contains(fixture.Tag)&&current.Contains("配色跟随"),"No-update response omitted current version or release changes");Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Fresh installation falsely reports a completed update");
        File.AppendAllText(Path.Combine(fixture.Root,fixture.Relative.Replace('/',Path.DirectorySeparatorChar)),"UNVERIFIED");Need(LocalProgramNotes.Read(fixture.Root,fixture.Version)==null,"Unverified notes with a bad hash were displayed");Need(!LocalProgramNotes.CurrentLog(fixture.Root,"当前",fixture.Version).Contains("UNVERIFIED"),"Rejected notes leaked into the log");fixture.Restore();
        fixture.Inventory.version="0.0.0.1";Write(Path.Combine(fixture.Root,"manifest.json"),fixture.Inventory);Need(LocalProgramNotes.Read(fixture.Root,fixture.Version)==null,"Mismatched installed manifest version accepted");fixture.Restore();
        string original=fixture.NoteText;fixture.NoteText=original.Replace("内部版本："+fixture.Version,"内部版本：0.0.0.1");fixture.Restore();Need(LocalProgramNotes.Read(fixture.Root,fixture.Version)==null,"Old release document was presented as the new version");fixture.NoteText=original.Replace("# "+fixture.Tag,"# v0.0.0-preview.1");fixture.Restore();Need(LocalProgramNotes.Read(fixture.Root,fixture.Version)==null,"Release heading did not bind to its filename");fixture.NoteText=original+new string('x',LocalProgramNotes.NotesLimit);fixture.Restore();Need(LocalProgramNotes.Read(fixture.Root,fixture.Version)==null,"Oversized release notes accepted");fixture.NoteText=original;fixture.Restore();
        fixture.Receipt(false);Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Failed transaction produced a success notice");fixture.Receipt(owner:Path.Combine(folder,"other-program"));Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Another installation's receipt produced a success notice");fixture.Receipt(version:"0.0.0.1");Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Old update receipt produced a current-version success notice");fixture.Receipt(changeNotes:false);Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Unchanged old release document was called this update's content");
        fixture.Receipt();string incoming=Path.Combine(fixture.Transaction,"incoming","update-manifest.json");var mismatched=Json.Deserialize<SoftwareManifest>(File.ReadAllText(incoming));mismatched.files.First(file=>file.path=="CodexLiveBackground.exe").sha256=new string('f',64);Write(incoming,mismatched);Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Wrong updater payload fingerprint accepted");fixture.Receipt();
        string ownerMarker=Path.Combine(fixture.Transaction,"previous",".codex-background-install.json");File.Delete(ownerMarker);Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Unowned transaction was guessed to belong to this installation");fixture.Receipt();
        string assets=Path.Combine(fixture.State,"pets","private-material.bin"),prefs=Path.Combine(fixture.State,"pet-settings.json");Directory.CreateDirectory(Path.GetDirectoryName(assets));File.WriteAllText(assets,"user-owned material");File.WriteAllText(prefs,"{\"custom\":true}");string assetHash=SoftwareUpdate.Hash(assets),prefsHash=SoftwareUpdate.Hash(prefs);
        notes=LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version);Need(notes!=null&&notes.Transaction=="rollback-fixture","Verified completed update was not detected");LocalProgramNotes.MarkShown(fixture.Root,fixture.State,notes);Need(File.Exists(Path.Combine(fixture.State,"updates","last-shown-update.json")),"One-time receipt was not recorded");Need(LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version)==null,"Same completed update would be announced on every startup");Need(SoftwareUpdate.Hash(assets)==assetHash&&SoftwareUpdate.Hash(prefs)==prefsHash,"Acknowledgement changed user materials/settings");Need(LocalProgramNotes.CurrentLog(fixture.Root,"当前",fixture.Version).Contains("配色跟随"),"Acknowledgement hides notes from later manual checks");
        string marker=Path.Combine(fixture.State,"updates","last-shown-update.json");File.Delete(marker);
        Application.EnableVisualStyles();var lookup=(UpdateLookupState)typeof(SoftwareUpdate).GetField("Lookup",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);bool hadCache=lookup.HasCache;var cached=lookup.Cached;DateTime cachedUntil=lookup.CachedUntilUtc;
        try{using(var form=(Form)Activator.CreateInstance(typeof(Manager),Private,null,new object[]{false},null)){
            IntPtr handle=form.Handle;Set(form,"root",fixture.Root);Set(form,"stateDirectory",fixture.State);Set(form,"liveStatusEnabled",true);var log=Field<TextBox>(form,"log");
            Lookup(lookup,fixture.Version);Invoke(form,"BeginSoftwareUpdate");Until(()=>!Field<bool>(form,"updatingSoftware")&&log.Text.Contains("当前版本更新内容"),"Manual no-update check did not display current release notes");Need(log.Text.Contains("配色跟随")&&log.Text.Contains(fixture.Tag),"Actual no-update UI branch omitted the verified note body");Need(!form.Visible,"UI test displayed the manager");
            Set(form,"pendingInstalledUpdate",LocalProgramNotes.Pending(fixture.Root,fixture.State,fixture.Version));Invoke(form,"TryShowInstalledUpdateNotes");Need(Field<LocalProgramNotes>(form,"pendingInstalledUpdate")!=null&&!File.Exists(marker),"Hidden manager consumed an unseen startup notice");
            Invoke(form,"DisplayInstalledUpdateNotes");Until(()=>File.Exists(marker),"Displayed update notice was not acknowledged");Need(log.Text.Contains("本次程序更新已完成"),"Installed update notice not appended");log.Text="连接失败：fixture diagnostic";Need(log.Text.StartsWith("连接失败：fixture diagnostic")&&log.Text.Contains("本次程序更新已完成"),"Startup notice overwrote a connection failure or disappeared immediately");Set(form,"retainUpdateNotesUntil",DateTime.UtcNow.AddSeconds(-1));log.Text="后续操作日志";Need(log.Text=="后续操作日志","Startup text protection did not expire");
            var newer=new Version(fixture.Version.Major,fixture.Version.Minor,fixture.Version.Build,fixture.Version.Revision+1);Lookup(lookup,newer);Invoke(form,"CheckSoftwareUpdate");Until(()=>log.Text.StartsWith("发现新版本"),"Available-update notice was not emitted");Need(!log.Text.Contains("配色跟随")&&!log.Text.Contains("当前版本更新内容"),"Current release notes were misrepresented as an available newer version's changes");Need(!form.Visible,"Update checks showed a real manager window");
        }}finally{lock(lookup.Gate){lookup.HasCache=hadCache;lookup.Cached=cached;lookup.CachedUntilUtc=cachedUntil;}}
        Need(SoftwareUpdate.Hash(assets)==assetHash&&SoftwareUpdate.Hash(prefs)==prefsHash,"UI checks changed user-owned data");
        File.WriteAllText(report,Json.Serialize(new{pass=true,checks,verifiedLocalNotes=true,manualNoUpdateNotes=true,successReceiptBoundToRoot=true,oncePerInstalledVersion=true,hiddenNoticeDeferred=true,diagnosticsPreserved=true,boundedLogRetentionSeconds=60,realUpdateOrNetworkRun=false,visibleUi=false}));return 0;
    }catch(Exception error){File.WriteAllText(report,Json.Serialize(new{pass=false,checks,error=error.ToString()}));return 1;}}
}
